sys_ui_action.script:
if (current.kyc_case.customer_type == 'individual') {
    var inputs = {};
    inputs['industry'] = current.kyc_case.individual.ri_industry.toString(); // String 
    inputs['country'] = current.kyc_case.individual.ri_country_of_domicile.toString(); // String 
    inputs['payout'] = current.kyc_case.individual.ri_payout_jurisdiction.toString(); // String 
    inputs['complexity_of_ownership'] = current.kyc_case.individual.ri_complexity_of_ownership.toString(); // String 
    inputs['business_year'] = current.kyc_case.individual.ri_business_start_year.toString(); // String 
    inputs['trade_frequency'] = current.kyc_case.individual.ri_expected_trade_frequency.toString(); // String 
    inputs['expected_fx_volume'] = current.kyc_case.individual.ri_expected_fx_volume.toString(); // String 
    gs.info('Inputs being sent: ' + JSON.stringify(inputs));

    // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
    var result = sn_fd.FlowAPI.getRunner().subflow('x_vuram_financia_0.risk__individual').inForeground().withInputs(inputs).run();
    var outputs = result.getOutputs();

    // Get Outputs:
    // Note: outputs can only be retrieved when executing synchronously.	
    var risk_score = outputs['risk_score']; // Floating Point Number
    var risk_level = outputs['risk_level']; // Choice
    var individual = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');
    individual.get(current.kyc_case.individual.sys_id);
    individual.risk_score = risk_score;
    individual.risk_level = risk_level;
    individual.update();
    current.state = 5;
    current.update();
} else if (current.kyc_case.customer_type == 'entity') {
    var inputs1 = {};
    inputs1['industry'] = current.kyc_case.entity.ri_industry.toString(); // String 
    inputs1['country'] = current.kyc_case.entity.ri_country_of_domicile.toString(); // String 
    inputs1['payout'] = current.kyc_case.entity.ri_payout_jurisdiction.toString(); // String 
    inputs1['complexity_of_ownership'] = current.kyc_case.entity.ri_complexity_of_ownership.toString(); // String 
    inputs1['business_year'] = current.kyc_case.entity.ri_business_start_year.toString(); // String 
    inputs1['trade_frequency'] = current.kyc_case.entity.ri_expected_trade_frequency.toString(); // String 
    inputs1['expected_fx_volume'] = current.kyc_case.entity.ri_expected_fx_volume.toString(); // String 
    gs.info('Inputs being sent entity: ' + JSON.stringify(inputs1));

    // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
    var result1 = sn_fd.FlowAPI.getRunner().subflow('x_vuram_financia_0.risk__individual').inForeground().withInputs(inputs1).run();
    var outputs1 = result1.getOutputs();

    // Get Outputs:
    // Note: outputs can only be retrieved when executing synchronously.	
    var risk_score1 = outputs1['risk_score']; // Floating Point Number
    var risk_level1 = outputs1['risk_level']; // Choice
    var entity = new GlideRecord('x_vuram_financia_0_fcc_kyc_entity_details');
    entity.get(current.kyc_case.entity.sys_id);
    entity.risk_score = risk_score1;
    entity.risk_level = risk_level1;
    entity.update();
    current.state = 5;
    current.update();
}
// Call utility
var au = new ActionUtils();
au.postInsert(current);
